"""Committed fixtures load, match their schema and are regenerated byte-identically."""

from __future__ import annotations

import json
import sys

import numpy as np
import pytest

from tools.qkdev import fixtures


@pytest.mark.parametrize("fx", fixtures.FIXTURES, ids=lambda f: f.name)
def test_fixture_schema_and_determinism(fx: fixtures.Fixture) -> None:
    path = fixtures.fixture_path(fx)
    assert path.exists(), f"run: uv run python -m tools.qkdev fixtures make ({path.name})"
    data = fixtures.load(fx.name)
    if sys.platform == "linux":
        # DQ-09 byte-identity is defined on Linux (the CI lint job runs `fixtures make --check`).
        assert path.read_bytes() == fixtures.fixture_bytes(fx)
    else:
        # NumPy's normal sampler can call libm in its tail, so other platforms may differ in
        # the last bit; the committed values must still agree closely.
        fresh = fx.build(np.random.default_rng(fx.seed), fx.params)
        for key, values in fresh.items():
            np.testing.assert_allclose(data[key].astype(np.float64), values, rtol=1e-12)
    assert data["x"].dtype == np.float64
    assert data["x"].shape == (int(fx.params["n"]),)
    if "y" in data:
        assert data["y"].shape == data["x"].shape
    meta = json.loads(str(data["meta"]))
    assert meta["seed"] == fx.seed
    assert meta["qkern_fixture_version"] == fixtures.FIXTURE_VERSION


def test_fixtures_total_size_under_2mb() -> None:
    total = sum(fixtures.fixture_path(fx).stat().st_size for fx in fixtures.FIXTURES)
    assert total <= 2 * 1024 * 1024


def test_fixture_contents() -> None:
    nan_runs = fixtures.load("nan_runs_10k")["x"].astype(np.float64)
    assert np.isnan(nan_runs).mean() > 0.05
    inf = fixtures.load("inf_spikes_5k")["x"].astype(np.float64)
    assert np.isposinf(inf).any()
    assert np.isneginf(inf).any()
    offset = fixtures.load("offset_1e9_10k")["x"].astype(np.float64)
    assert abs(float(np.mean(offset)) - 1e9) < 1.0
